# CLI Interface
# ---------------------------------------------------------------------------

def cmd_archive(store: RoomStore, index: RAGIndex) -> None:
    """Run the archive cycle."""
    manager = ArchiveManager(store, index)
    results = manager.run_archive_cycle()
    if results:
        print("\n📊 Archive Summary:")
        for r in results:
            print(f"  - {r['room_name']}: {r['message_count']} msgs, "
                  f"{r['chunk_count']} chunks indexed")
    else:
        print("\nℹ️  No inactive rooms found to archive.")


def cmd_search(store: RoomStore, index: RAGIndex, query: str) -> None:
    """Search the RAG index."""
    manager = ArchiveManager(store, index)
    results = manager.retrieve(query, top_k=5)
    if results:
        print(f"\n🔍 Search results for: '{query}'")
        print("-" * 60)
        for i, r in enumerate(results, 1):
            print(f"\n[{i}] Score: {r['score']} | Room: {r['room_name']}")
            print(f"    Text: {r['text'][:150]}...")
    else:
        print(f"\n🔍 No results found for: '{query}'")


def cmd_list_archived(store: RoomStore, index: RAGIndex) -> None:
    """List archived rooms."""
    archived = index.list_archived()
    if not archived:
        print("\n📂 No archived rooms yet.")
        return
    print(f"\n📂 Archived rooms ({len(archived)}):")
    print("-" * 60)
    for a in archived:
        dt = datetime.fromtimestamp(a["archived_at"], tz=timezone.utc)
        print(f"  - {a['room_name']} ({a['room_id']})")
        print(f"    Archived: {dt.isoformat()}")
        print(f"    Messages: {a['message_count']}, Chunks: {a['chunk_count']}")
        print(f"    Summary: {a['summary'][:100]}...")
        print()


def cmd_demo(store: RoomStore, index: RAGIndex) -> None:
    """Create demo data and run full cycle."""
    create_demo_rooms(store)
    cmd_archive(store, index)
    print("\n" + "=" * 60)
    print("Now testing RAG retrieval...")
    cmd_search(store, index, "RAG indexelés visszakeresés")
    cmd_search(store, index, "archiválás SQLite TF-IDF")
    cmd_list_archived(store, index)


def cmd_status(store: RoomStore, index: RAGIndex) -> None:
    """Show status of active and archived rooms."""
    active_ids = store.list_active_rooms()
    archived_ids = store.list_archived_rooms()
    print(f"\n📊 Status:")
    print(f"  Active rooms:   {len(active_ids)}")
    print(f"  Archived rooms: {len(archived_ids)}")
    for rid in active_ids:
        room = store.load_room(rid)
        if room:
            elapsed = (time.time() - room.last_activity) / 3600
            status = "⚠️ INACTIVE" if room.is_inactive() else "✅ active"
            print(f"    [{status}] {room.name} — {elapsed:.1f}h since last activity")


def main():
    """Main entry point with CLI argument handling."""
    store = RoomStore(ROOMS_DIR, ARCHIVE_DIR)
    index = RAGIndex(INDEX_DB_PATH)

    if len(sys.argv) < 2:
        print(__doc__)
        print("\nUsage:")
        print(f"  python {sys.argv[0]} demo      — Create demo data & run full cycle")
        print(f"  python {sys.argv[0]} archive   — Archive inactive rooms (48h+)")
        print(f"  python {sys.argv[0]} search <query> — Search RAG index")
        print(f"  python {sys.argv[0]} list      — List archived rooms")
        print(f"  python {sys.argv[0]} status    — Show room status")
        index.close()
        return

    cmd = sys.argv[1].lower()

    try:
        if cmd == "demo":
            cmd_demo(store, index)
        elif cmd == "archive":
            cmd_archive(store, index)
        elif cmd == "search":
            query = " ".join(sys.argv[2:]) if len(sys.argv) > 2 else ""
            if not query:
                print("Error: provide a search query")
                print(f"  python {sys.argv[0]} search \"your query here\"")
            else:
                cmd_search(store, index, query)
        elif cmd == "list":
            cmd_list_archived(store, index)
        elif cmd == "status":
            cmd_status(store, index)
        else:
            print(f"Unknown command: {cmd}")
            print(f"Run 'python {sys.argv[0]}' for usage.")
    finally:
        index.close()


if __name__ == "__main__":
    main()